// Generated by lib/generate-noun.ts from qsm.json. Do not hand-edit; run
// `bun lib/generate-noun.ts plugins/<name>` again after changing qsm.json.

export type Secrets = {
  set(options: {
    key: string;
    folder?: string;
    gui?: boolean;
  }): Promise<unknown>;
  askpassEnable(options: {
    sudo?: boolean;
    ssh?: boolean;
    git?: boolean;
    decide?: boolean;
  }): Promise<unknown>;
  has(options: {
    key: string;
    folder?: string;
  }): Promise<unknown>;
  list(options: {
    folder?: string;
  }): Promise<unknown>;
  inspect(options: {
    folder?: string;
  }): Promise<unknown>;
  rm(options: {
    key: string;
    folder?: string;
  }): Promise<unknown>;
  rename(options: {
    from: string;
    to: string;
    folder?: string;
    toFolder?: string;
    legacy?: boolean;
  }): Promise<unknown>;
  prune(options: {
    dryRun?: boolean;
  }): Promise<unknown>;
  guard(): Promise<unknown>;
  capture(options: {
    session?: string;
    cwd?: string;
  }): Promise<unknown>;
  captures(): Promise<unknown>;
  mask(options: {
    id?: (string)[];
    all?: boolean;
  }): Promise<unknown>;
  scrub(options: {
    transcript: string;
    detach?: boolean;
  }): Promise<unknown>;
  render(options: {
    template: string;
    out: string;
    session?: string;
  }): Promise<unknown>;
  clean(options: {
    session?: string;
  }): Promise<unknown>;
  doctor(options: {
    folder?: string;
  }): Promise<unknown>;
};

declare module 'claude-code' {
  interface EngineInterface {
    secrets: Secrets;
  }
}

// The session state qsm-secrets keeps. Self-contained, as a plugin's type contract must be: the row
// is spelt here as lib/capture-row.ts's CaptureListing is.

/** A row of `qsm-secrets captures`, never a value. */
export type ReviewListing = {
  namespace: string;
  key: string;
  kind: string;
  capturedAt: string;
  session: string | null;
  cwd: string | null;
};

declare module "claude-code" {
  interface PluginState {
    "qsm-secrets": {
      /** The review pane's rows as `qsm-secrets captures` last listed them (null before the first
       * load), and the outcome code of each delete that failed, by id. */
      review: Shaped<{ listed: ReviewListing[] | null; failed: Record<string, string> }>;
    };
  }
}
